import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE t (v TEXT)');
  const ins = db.prepare('INSERT INTO t (v) VALUES (?)');
  console.log(JSON.stringify(ins.run('a')));
  console.log(JSON.stringify(ins.run('b')));
  const r = ins.run('c');
  console.log(r.lastInsertRowid, r.changes, Object.keys(r).join(','));
  console.log(db.prepare('UPDATE t SET v = v || ?').run('!').changes);
  db.close();
}
